entries[169600] = { ["name"] = "Recipe: Potion of Empowered Proximity", ["text"] = "Rank 3\nBinds when picked up\nUse: Teaches you how to craft a Potion of Empowered Proximity more efficiently.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (170)\nRequires The Unshackled\n- Revered\nSell Price:\nPotion of Empowered Proximity\nUse: Empowers your abilities, increasing your Primary Stat by 108 for 25 sec. Your primary stat is further increased by the number of enemies within 8 yards of you, up to a maximum of ( 108 * 5). (5 Min Cooldown)\nSell Price:\nRequires Zin'anthid (8), Winter's Kiss (3), Crystal Vial" }
entries[169601] = { ["name"] = "Recipe: Potion of Reconstitution", ["text"] = "Rank 3\nBinds when picked up\nUse: Teaches you how to craft a Potion of Reconstitution more efficiently.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (170)\nRequires The Unshackled\n- Revered\nSell Price:\nPotion of Reconstitution\nUse: Puts the imbiber in an elevated state of focus where they can restore up to ( 816 * 10) mana over 10 sec, but they are defenseless until their focus is broken. (5 Min Cooldown)\nSell Price:\nRequires Zin'anthid (8), Akunda's Bite (3), Crystal Vial" }
entries[169602] = { ["name"] = "Recipe: Potion of Focused Resolve", ["text"] = "Rank 3\nBinds when picked up\nUse: Teaches you how to craft a Potion of Focused Resolve more efficiently.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (170)\nRequires The Unshackled\n- Revered\nSell Price:\nPotion of Focused Resolve\nUse: Narrow your gaze to a single foe. Your damaging abilities will mark the target, increasing your chance to critically strike them up to 20%. Damaging a new target will reset your focus. Lasts 25 sec. Does not work on targets above 50. (5 Min Cooldown)\nSell Price:\nRequires Zin'anthid (8), Winter's Kiss (3), Crystal Vial" }
entries[169603] = { ["name"] = "Recipe: Greater Mystical Cauldron", ["text"] = "Rank 3\nBinds when picked up\nUse: Teaches you how to craft a Greater Mystical Cauldron more efficiently.\nChance to create multiple cauldrons.\nRequires Kul Tiran Alchemy (175)\nRequires The Unshackled\n- Exalted\nSell Price:\nGreater Mystical Cauldron\nBinds to Warband\nUse: Creates a cauldron that raid members can use to gain the benefit of a flask appropriate to their class and talents. Cauldron has 30 uses and lasts for 10 min.\nSell Price:\nRequires Greater Flask of the Currents (3), Greater Flask of Endless Fathoms (3), Greater Flask of the Vast Horizon (3), Greater Flask of the Undertow (3), Expulsom (4)" }
