entries[169609] = { ["name"] = "Schematic: Super-Charged Engine", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Super-Charged Engine.\nCraft a Super-Charged Engine.\nRequires Kul Tiran Engineering (160)\nSuper-Charged Engine\nUse: Combine a Monelite Reinforced Chassis and a Super-Charged Engine to create a Xiwyllag ATV. This is a very fast mount.\nRequires Monelite Ore (100), Storm Silver Ore (50), Insulated Wiring (25), Chemical Blasting Cap (12), Expulsom (8)" }
