entries[169899] = { ["name"] = "Polished Skull Trophy", ["text"] = "Rank 4\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Conflict and Strife.\nMajor Power:\nConflict\nTeaches you the PvP Talent and allows its use against all enemies of Azeroth.\n\nWhile you are stunned, the defensive benefit from your Versatility is increased by 50%.\n\nDispelling, interrupting, or applying a loss of control effect grants a stack of Strife. Versatility granted by Strife is doubled for the next 5 sec.\nMinor Power:\nStrife\nYour spells and abilities have a chance to increase your Versatility by 11 for 14 sec, stacking up to 8 times. Being the vicitim of a loss of control or movement impairing effect also grants a stack of Strife." }
entries[169900] = { ["name"] = "Rib-Bone Choker of Dominance", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Conflict and Strife.\nRequires a PVP rating of 1400 or higher in the previous week.\nLearn Rank 3 Conflict and Strife on another character to unlock this essence.\nMajor Power:\nConflict\nTeaches you the PvP Talent and allows its use against all enemies of Azeroth.\n\nWhile you are stunned, the defensive benefit from your Versatility is increased by 50%.\n\nDispelling, interrupting, or applying a loss of control effect grants a stack of Strife. Versatility granted by Strife is doubled for the next 5 sec.\nMinor Power:\nStrife\nYour spells and abilities have a chance to increase your Versatility by 11 for 14 sec, stacking up to 8 times. Being the vicitim of a loss of control or movement impairing effect also grants a stack of Strife." }
entries[169901] = { ["name"] = "Etched Bone Trophy of the Vanquished", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Conflict and Strife.\nRequires a PVP rating of 1000 or higher in the previous week.\nMajor Power:\nConflict\nTeaches you the PvP Talent and allows its use against all enemies of Azeroth.\n\nWhile you are stunned, the defensive benefit from your Versatility is increased by 50%.\nMinor Power:\nStrife\nYour spells and abilities have a chance to increase your Versatility by 11 for 14 sec, stacking up to 5 times. Being the vicitim of a loss of control or movement impairing effect also grants a stack of Strife." }
entries[169902] = { ["name"] = "Finger-Bone Trophy of Battle", ["text"] = "Rank 1\nBinds when picked up\nUnique\nUse: Infuse your Heart of Azeroth with Conflict and Strife.\nMajor Power:\nConflict\nTeaches you the following PvP Talent, and allows its use against all enemies of Azeroth.\n\nVengeance\n[Havoc: First of the IllidariRequires Demon HunterMetamorphosis grants 10% versatility and its cooldown is reduced by 60 sec.] [Vengeance: Cleansed by FlamePvP TalentRequires Demon Hunter (Havoc, Vengeance)Requires level 20 (Havoc)Requires level 20 (Vengeance)Immolation Aura dispels a magical effect on you when cast.]\nMinor Power:\nStrife\nYour spells and abilities have a chance to increase your Versatility by 11 for 8 sec, stacking up to 5 times. Being the victim of a loss of control or movement impairing effect also grants a stack of Strife. (500ms cooldown)" }
