entries[170167] = { ["name"] = "Eel Filet", ["text"] = "Binds when picked up\nUnique\n\"A fresh, meaty piece of an abyssal eel. One of your new allies in Nazjatar might have use of this.\"" }
entries[170168] = { ["name"] = "Glyph of the Cold Waves", ["text"] = "Classes: Mage\nUse: Permanently teaches you this glyph.\n\nYour Water Elemental is replaced by a Cresting Wave Elemental. Exclusive with: Glyph of the Unbound Elemental Glyph of Evaporation Glyph of the Tides Glyph of Storm's Wake Glyph of the Dark Depths Glyph of Steaming Fury\nSell Price:" }
entries[170169] = { ["name"] = "Technique: Glyph of the Cold Waves", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to inscribe a Glyph of the Cold Waves.\nRequires Kul Tiran Inscription (150)\nSell Price:\nGlyph of the Cold Waves\nClasses: Mage\nUse: Permanently teaches you this glyph.\n\nYour Water Elemental is replaced by a Cresting Wave Elemental. Exclusive with: Glyph of the Unbound Elemental Glyph of Evaporation Glyph of the Tides Glyph of Storm's Wake Glyph of the Dark Depths Glyph of Steaming Fury\nSell Price:\nRequires Light Parchment , Crimson Ink (10), Ultramarine Ink (30)" }
entries[170170] = { ["name"] = "Fermented Deviate Fish", ["text"] = "Binds when picked up\nUse: Eat me. (10 Sec Cooldown)\nSell Price:" }
entries[170171] = { ["name"] = "Giant Crab Leg", ["text"] = "Binds when picked up\nUnique\n\"Looks succulent. One of your new allies in Nazjatar might have use of this.\"" }
entries[170172] = { ["name"] = "Brightspine Shell", ["text"] = "Binds when picked up\nUnique\nUse: Put the bright, spiky shell on your head, which deals Physical damage to enemies that attack you in combat, but increases the radius that enemies detect you.\n\nOnly usable in Kul Tiras, Zandalar, and Nazjatar. (10 Sec Cooldown)\n4 Charges\n\"The shell glitters in the sunlight.\"\nSell Price:" }
entries[170173] = { ["name"] = "Glyph of Dire Bees", ["text"] = "Classes: Hunter\nUse: Permanently teaches you this glyph.\n\nYour Dire Beast ability calls on bees!! DIRE BEES!!! Exclusive with: Glyph of Arachnophobia Glyph of Nesingwary's Nemeses Glyph of the Dire Stable\nSell Price:" }
entries[170174] = { ["name"] = "Muck Slime", ["text"] = "Binds when picked up\nUse: Increases chance to Dodge by 35% for 20 min and grants increased Haste when you dodge an attack.\n\nOnly usable in Kul Tiras, Zandalar, and Nazjatar. (1s cooldown) (10 Sec Cooldown)\n\"It seems particularly slimy.\"\nSell Price:" }
entries[170175] = { ["name"] = "Technique: Glyph of Dire Bees", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to inscribe a Glyph of Dire Bees.\nRequires Kul Tiran Inscription (150)\nSell Price:\nGlyph of Dire Bees\nClasses: Hunter\nUse: Permanently teaches you this glyph.\n\nYour Dire Beast ability calls on bees!! DIRE BEES!!! Exclusive with: Glyph of Arachnophobia Glyph of Nesingwary's Nemeses Glyph of the Dire Stable\nSell Price:\nRequires Light Parchment , Crimson Ink (10), Choral Honey (10), Ultramarine Ink (30)" }
entries[170176] = { ["name"] = "Fathom Ray Wing", ["text"] = "Binds when picked up\nUnique\n\"A hard, rubbery exterior protects the soft meat within. One of your new allies in Nazjatar might have use of this.\"" }
entries[170177] = { ["name"] = "Exposed Fish", ["text"] = "Binds when picked up\nUnique\nUse: Place the fish down and kick it around. (10 Sec Cooldown)\nSell Price:" }
entries[170178] = { ["name"] = "Alpha Fin", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Summons a ridable wild snapdragon for 20 sec. On dismounting, the snapdragon will fight for you for 1 min. This is a very, VERY fast mount.\n\nOnly usable in Zandalar, Kul Tiras, and Nazjatar. (10 Sec Cooldown)\nSell Price:" }
entries[170179] = { ["name"] = "Snapdragon Scent Gland", ["text"] = "Binds when picked up\nUnique\nUse: Smash the gland and become the pack leader, summoning snapdragons to fight for you for 1 min.\n\nOnly usable in Zandalar, Kul Tiras, and Nazjatar. (10 Sec Cooldown)\n\"The gland of a snapdragon matriarch or patriarch marks the holder as a pack leader.\"\nSell Price:" }
entries[170180] = { ["name"] = "Razorshell", ["text"] = "Binds when picked up\nUnique\nUse: Summons a rideable shell for 5 min that dismounts and stuns enemy players.\n\nCan only be used in War Mode in Mechagon, Nazjatar, Zandalar, and Kul Tiras. (10 Sec Cooldown)\nSell Price:" }
entries[170181] = { ["name"] = "Tidal Guard", ["text"] = "Binds when picked up\nUnique\nUse: Summons a tidal guardian to assist you for 2 min.\n\nOnly usable in Kul Tiras, Zandalar, and Nazjatar. (10 Sec Cooldown)\nSell Price:" }
entries[170182] = { ["name"] = "Voltscale Shield", ["text"] = "Binds when picked up\nUse: Strikes nearby enemies with tidal guardian lightning, inflicting Nature damage and increasing Nature damage taken.\n\nOnly usable in Kul Tiras, Zandalar, and Nazjatar. (10 Sec Cooldown)\n10 Charges\nSell Price:" }
entries[170183] = { ["name"] = "Reefwalker Bark", ["text"] = "Binds when picked up\nUnique\n\"A hard, yet spongy substance. One of your new allies in Nazjatar might have use of this.\"" }
