entries[170186] = { ["name"] = "Abyss Pearl", ["text"] = "Binds when picked up\nUnique\nUse: Place a pearl from the deeps. Grants Mastery to nearby players in Nazjatar. (10 Sec Cooldown)\nSell Price:" }
