entries[170208] = { ["name"] = "Recipe: Potion of Unbridled Fury", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Potion of Unbridled Fury more efficiently.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (170)\nSell Price:\nPotion of Unbridled Fury\nUse: Fill yourself with unbridled energy, giving your offensive spells and attacks a chance to do an additional 1344 Fire damage to your target. Lasts 1 min. (5 Min Cooldown)\nSell Price:\nRequires Zin'anthid (6), Crystal Vial" }
entries[170209] = { ["name"] = "Recipe: Potion of Wild Mending", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Potion of Wild Mending more efficiently.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (170)\nSell Price:\nPotion of Wild Mending\nUse: Empowers your mind, giving your healing abilities a chance to restore an additional 2017 health to your target. Lasts 1 min. (5 Min Cooldown)\nSell Price:\nRequires Zin'anthid (6), Crystal Vial" }
entries[170210] = { ["name"] = "Recipe: Abyssal Healing Potion", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Abyssal Healing Potion more efficiently.\nChance to create multiple potions.\nRequires Kul Tiran Alchemy (170)\nSell Price:\nAbyssal Healing Potion\nUse: Restores 16000 health. (5 Min Cooldown)\nSell Price:\nRequires Zin'anthid (2), Crystal Vial" }
entries[170211] = { ["name"] = "Recipe: Famine Evaluator And Snack Table", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft a Famine Evaluator And Snack Table more efficiently.\nPrepare F.E.A.S.T.s more efficiently, using significantly fewer materials.\nRequires Kul Tiran Cooking (175)\nSell Price:\nFamine Evaluator And Snack Table\nUse: Set out a F.E.A.S.T. to feed up to 35 people in your raid or party!\n\nRestores 50769 health and 30769 mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 50 in a stat for 1 hour.\nSell Price:\nRequires Viper Fish (15), Ionized Minnow (15), Stringy Loins (15), Meaty Haunch (15), Fresh Potato (20), S.P.A.R.E. Crate" }
entries[170212] = { ["name"] = "Recipe: Mecha-Bytes", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft Mecha-Bytes.\nPrepare Mecha-Bytes.\nRequires Kul Tiran Cooking (150)\nSell Price:\nMecha-Bytes\nUse: Eat me?\n\"Contains a jagged metal rusty-O!\"\nSell Price:\nRequires Spare Parts (25)" }
entries[170213] = { ["name"] = "Formula: Naga Hide", ["text"] = "Rank 3\nBinds when picked up\nUnique\nUse: Teaches you how to craft Naga Hide more efficiently.\nPermanently enchant a weapon with a naga spell of protection. When you Block, Dodge, or Parry, you have a chance to increase Strength or Agility by 4 for 15 sec. Additionally, while active, your skin is covered in thick scales, allowing you to absorb 1573 damage. Cannot be applied to items above level 376.\n\nGreatly reduced materials.\nRequires Kul Tiran Enchanting (175)\nSell Price:" }
