entries[170586] = { ["name"] = "Pattern: Uncanny Combatant's Bow", ["text"] = "Rank 2\nBinds when picked up\nUnique\nUse: Teaches you how to craft an Uncanny Combatant's Bow more efficiently.\nReduce the materials required to craft an Uncanny Combatant's Bow.\nRequires Kul Tiran Leatherworking (1)\nSell Price:\nAlliance\nUncanny Combatant's Bow\nBinds when equipped\nRanged Bow\n13 - 18 Damage Speed 3.00\n(5.2 damage per second)\n+7 Agility\n+10 Stamina\nDurability 120 / 120\nSell Price:\nHorde\nUncanny Combatant's Bow\nBinds when equipped\nRanged Bow\n13 - 18 Damage Speed 3.00\n(5.2 damage per second)\n+7 Agility\n+10 Stamina\nDurability 120 / 120\nSell Price:\nRequires Dredged Leather (23), Cragscale (23), Blood-Stained Bone (30), Expulsom (6)" }
